"""
Extract failed and ``fixme``-annotated tests from a Playwright JSON report.

This is a CI helper used by the end-to-end browser test workflow. It reads the
Playwright JSON reporter output for a single browser run and produces two small
JSON artifacts (``failures.json`` and ``fixme_tests.json``) that are later
aggregated across runs/browsers to detect flaky tests.
"""

from __future__ import annotations

import json
import os
from pathlib import Path

# Maximum length of an error message that we keep in the artifacts. Playwright
# error messages (including stack traces) can be huge, so we normalise and
# truncate them to keep the aggregated payloads small.
MAX_ERROR_LENGTH = 300


def truncate_error(message: str) -> str:
    """Normalise and truncate a Playwright error message.

    Leading/trailing whitespace is stripped and any newline characters are
    replaced with spaces so the message fits on a single line. Messages of
    ``MAX_ERROR_LENGTH`` characters or fewer are returned unchanged; longer
    messages are truncated to exactly ``MAX_ERROR_LENGTH`` characters with
    ``"..."`` appended.
    """
    if not message:
        return ""
    normalized = str(message).strip()
    for newline in ("\r\n", "\n", "\r"):
        normalized = normalized.replace(newline, " ")
    if len(normalized) <= MAX_ERROR_LENGTH:
        return normalized
    return normalized[:MAX_ERROR_LENGTH] + "..."


def extract_test_title(spec: dict) -> str:
    """Build the full, human-readable title for a Playwright spec.

    Uses ``spec['location']['file']`` as the file path (falling back to
    ``"unknown"`` when the ``location`` key is absent) and joins the non-empty
    elements of ``spec['titlePath']`` with ``" > "``. When there are no
    non-empty title parts, only the file path is returned.
    """
    file_path = spec.get("location", {}).get("file", "unknown")
    title_parts = [part for part in spec.get("titlePath", []) if part]
    if not title_parts:
        return file_path
    return f"{file_path}: {' > '.join(title_parts)}"


def _extract_error(test: dict) -> str:
    """Return a single, normalised error message for a failed test."""
    for result in test.get("results", []):
        error = result.get("error")
        if isinstance(error, dict) and error.get("message"):
            return truncate_error(error["message"])
        errors = result.get("errors")
        if errors:
            first = errors[0]
            if isinstance(first, dict) and first.get("message"):
                return truncate_error(first["message"])
    return ""


def _is_failed(test: dict) -> bool:
    """Return ``True`` when a Playwright test counts as a failure."""
    if test.get("status") == "unexpected":
        return True
    return any(
        result.get("status") in ("failed", "timedOut")
        for result in test.get("results", [])
    )


def extract_failures(suites: list) -> list:
    """Recursively collect failed/unexpected tests from Playwright suites."""
    failures: list = []
    for suite in suites or []:
        failures.extend(extract_failures(suite.get("suites", [])))
        for spec in suite.get("specs", []):
            for test in spec.get("tests", []):
                if not _is_failed(test):
                    continue
                failures.append(
                    {
                        "test": extract_test_title(spec),
                        "status": test.get("status", ""),
                        "error": _extract_error(test),
                        "spec_file": spec.get("location", {}).get(
                            "file", suite.get("file", "unknown")
                        ),
                    }
                )
    return failures


def extract_fixme_tests(suites: list) -> list:
    """Recursively collect ``fixme``-annotated tests from Playwright suites."""
    fixme_tests: list = []
    for suite in suites or []:
        fixme_tests.extend(extract_fixme_tests(suite.get("suites", [])))
        for spec in suite.get("specs", []):
            for test in spec.get("tests", []):
                annotations = test.get("annotations", []) or []
                if any(annotation.get("type") == "fixme" for annotation in annotations):
                    fixme_tests.append(
                        {
                            "test": extract_test_title(spec),
                            "status": test.get("status", ""),
                            "annotations": annotations,
                        }
                    )
    return fixme_tests


def main() -> None:
    """Read the Playwright report and write the extracted artifacts."""
    results_json = os.environ.get("RESULTS_JSON", "")
    output_dir = os.environ.get("OUTPUT_DIR", "")
    browser = os.environ.get("BROWSER", "")
    run_id = os.environ.get("RUN_ID", "")

    output_path = Path(output_dir)
    output_path.mkdir(parents=True, exist_ok=True)

    results_path = Path(results_json) if results_json else None

    if not results_path or not results_path.exists():
        failures_payload = {"failures": [], "metadata": {"has_results": False}}
        fixme_payload: dict = {"fixme_tests": []}
    else:
        with results_path.open(encoding="utf-8") as handle:
            data = json.load(handle)
        suites = data.get("suites", [])
        failures_payload = {
            "failures": extract_failures(suites),
            "metadata": {
                "browser": browser,
                "run_id": run_id,
                "has_results": True,
            },
        }
        fixme_payload = {"fixme_tests": extract_fixme_tests(suites)}

    with (output_path / "failures.json").open("w", encoding="utf-8") as handle:
        json.dump(failures_payload, handle, indent=2)
    with (output_path / "fixme_tests.json").open("w", encoding="utf-8") as handle:
        json.dump(fixme_payload, handle, indent=2)


if __name__ == "__main__":
    main()
