"""
Analyse aggregated end-to-end browser test results and build a Slack report.

This CI helper consumes the per-run/per-browser artifacts produced by
``extract_e2e_test_results.py``, identifies tests that fail often enough to be
flaky-test candidates, and formats the outcome as a Slack Block Kit message.
"""

from __future__ import annotations

# Tests failing at or below this rate (relative to the number of runs that had
# data) are considered too rare to be worth flagging as flaky candidates.
MIN_FAILURE_RATE = 0.1

SLACK_CHANNEL = "airflow-3-ui"


def escape_slack_mrkdwn(text: str) -> str:
    """Escape the characters that are special in Slack's mrkdwn format.

    ``&`` is escaped first so that the ``&`` introduced by the ``<``/``>``
    replacements is not escaped a second time.
    """
    return (
        str(text)
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
    )


def _failure_count(value) -> int:
    """Return the number of failures represented by a ``failures_by_test`` value.

    The aggregated structure may store failures as a list of records, as an
    integer count, or as a dict containing a count/list, so we handle each of
    those shapes.
    """
    if isinstance(value, list):
        return len(value)
    if isinstance(value, dict):
        if "count" in value:
            return value["count"]
        for key in ("failures", "errors", "results"):
            if isinstance(value.get(key), list):
                return len(value[key])
        return 0
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, (int, float)):
        return value
    return 0


def _first_error(value) -> str:
    """Return a representative error message for a ``failures_by_test`` value."""
    if isinstance(value, list) and value:
        first = value[0]
        if isinstance(first, dict):
            return first.get("error", "")
        return str(first)
    if isinstance(value, dict):
        if value.get("error"):
            return value["error"]
        errors = value.get("errors")
        if isinstance(errors, list) and errors:
            first = errors[0]
            if isinstance(first, dict):
                return first.get("error") or first.get("message") or ""
            return str(first)
    return ""


def identify_flaky_candidates(failures_by_test: dict, runs_with_data: int) -> list:
    """Return tests whose failure rate exceeds ``MIN_FAILURE_RATE``.

    Each returned dict contains at least ``test`` (the test name) and
    ``failure_rate`` (a float in ``(0, 1]``). An empty list is returned when
    there is no data. Results are sorted by ``failure_rate`` descending.
    """
    if not failures_by_test or not runs_with_data:
        return []

    candidates = []
    for test, value in failures_by_test.items():
        count = _failure_count(value)
        if count <= 0:
            continue
        failure_rate = count / runs_with_data
        if failure_rate < MIN_FAILURE_RATE:
            continue
        candidates.append(
            {
                "test": test,
                "failure_rate": failure_rate,
                "failure_count": count,
            }
        )

    candidates.sort(key=lambda candidate: candidate["failure_rate"], reverse=True)
    return candidates


def _section(text: str) -> dict:
    """Build a Slack Block Kit ``section`` block with mrkdwn text."""
    return {"type": "section", "text": {"type": "mrkdwn", "text": text}}


def format_slack_message(
    failures_by_test: dict,
    fixme_tests: dict,
    flaky_candidates: list,
    runs: list,
    runs_with_data: int,
    repo: str,
) -> dict:
    """Format the aggregated analysis as a Slack Block Kit message dict."""
    total_runs = len(runs) if runs else 0

    blocks: list = [
        {
            "type": "header",
            "text": {"type": "plain_text", "text": "E2E Flaky Test Report"},
        },
        _section(
            f"*Repository:* {escape_slack_mrkdwn(repo)}\n"
            f"*Runs analyzed:* {total_runs} ({runs_with_data} with data)"
        ),
        {"type": "divider"},
    ]

    # Flaky test candidates.
    if flaky_candidates:
        lines = ["*Flaky test candidates (consider marking as `fixme`):*"]
        for candidate in flaky_candidates:
            name = escape_slack_mrkdwn(candidate.get("test", ""))
            rate = candidate.get("failure_rate", 0) or 0
            lines.append(f"• `{name}` — {rate * 100:.1f}%")
        blocks.append(_section("\n".join(lines)))
    else:
        blocks.append(_section("No flaky test candidates identified."))

    # Test failures.
    if failures_by_test:
        lines = ["*Test failures:*"]
        for test_name, value in failures_by_test.items():
            name = escape_slack_mrkdwn(test_name)
            count = _failure_count(value)
            error = escape_slack_mrkdwn(_first_error(value))
            entry = f"• `{name}` ({count} failure(s))"
            if error:
                entry += f": {error}"
            lines.append(entry)
        blocks.append(_section("\n".join(lines)))
    else:
        blocks.append(_section("No test failures detected."))

    # Tests already annotated as fixme.
    if fixme_tests:
        lines = ["*Tests currently marked as `fixme`:*"]
        for test_name in fixme_tests:
            lines.append(f"• `{escape_slack_mrkdwn(test_name)}`")
        blocks.append(_section("\n".join(lines)))

    text = (
        f"E2E Flaky Test Report for {repo}: "
        f"{len(failures_by_test)} failing test(s), "
        f"{len(flaky_candidates)} flaky candidate(s)"
    )

    return {"channel": SLACK_CHANNEL, "text": text, "blocks": blocks}
